:root{--forest:#174d2d;--leaf:#2e7d32;--lime:#94c946;--cream:#fffaf0;--paper:#f5eddb;--ink:#1e2b22;--orange:#c85e1c;--white:#fff;--shadow:0 18px 48px rgba(21,60,36,.14)}
    *{box-sizing:border-box} html{scroll-behavior:smooth} body{margin:0;background:var(--cream);color:var(--ink);font-family:Arial,Helvetica,sans-serif;line-height:1.5} a{color:inherit;text-decoration:none} img{display:block;width:100%}
    .wrap{width:min(1120px,calc(100% - 40px));margin:auto}.eyebrow{margin:0 0 10px;color:var(--orange);font-size:.78rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.display{font-family:Georgia,'Times New Roman',serif}.section{padding:88px 0}.section h2{margin:0;font-size:clamp(2rem,4vw,3.35rem);line-height:1.05}.section-head{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:32px}.section-head p:last-child{max-width:440px;margin:0;color:#5b655e}
    .top{position:sticky;top:0;z-index:10;background:rgba(255,250,240,.94);backdrop-filter:blur(14px);border-bottom:1px solid rgba(23,77,45,.12);box-shadow:0 8px 24px rgba(14,51,28,.06)}.nav{min-height:88px;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{display:flex;align-items:center;gap:10px;font-family:Georgia,serif;font-weight:700;color:var(--forest);line-height:1.04}.brand-top{gap:14px}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;background:var(--forest);color:var(--lime);font-size:19px}.brand-top .brand-mark{width:56px;height:56px;font-size:27px;box-shadow:0 8px 18px rgba(23,77,45,.22);animation:brandGlow 3.5s ease-in-out infinite}.brand-title{display:block;font-size:1.26rem;letter-spacing:-.02em}.brand small{display:block;color:var(--orange);font-family:Arial,sans-serif;font-size:.58rem;letter-spacing:.11em;text-transform:uppercase}.brand-top small{margin-top:5px;font-size:.66rem}.links{display:flex;align-items:center;gap:20px;font-size:.88rem;font-weight:700}.links a{position:relative;padding:8px 0}.links a:after{content:'';position:absolute;left:0;right:0;bottom:3px;height:2px;background:var(--orange);transform:scaleX(0);transform-origin:left;transition:transform .2s}.links a:hover{color:var(--orange)}.links a:hover:after{transform:scaleX(1)}.nav-call,.button{display:inline-flex;align-items:center;justify-content:center;border-radius:999px;background:var(--forest);color:white;padding:11px 18px;font-weight:800;transition:.2s}.nav-call:hover,.button:hover{background:var(--orange);transform:translateY(-1px)}
    .hero{min-height:680px;display:grid;align-items:center;background:linear-gradient(90deg,rgba(9,37,20,.9) 0%,rgba(9,37,20,.63) 50%,rgba(9,37,20,.14)),url('data:image/jpeg;base64,') center/cover}.hero-content{padding:100px 0;color:white}.hero-content>*{animation:heroReveal .8s cubic-bezier(.22,1,.36,1) both}.hero-content h1{animation-delay:.08s}.hero-content>p:not(.eyebrow){animation-delay:.16s}.hero-actions{animation-delay:.24s}.hero-shortcuts{animation-delay:.32s}.hero-note{animation-delay:.4s}.hero .eyebrow{color:#d8ef8d}.hero h1{max-width:760px;margin:0;font-size:clamp(3rem,8vw,6.3rem);line-height:.9;letter-spacing:-.05em}.hero h1 span{color:#d8ef8d}.hero p:not(.eyebrow){max-width:560px;margin:28px 0;color:#f4f6ed;font-size:1.1rem}.hero-actions{display:flex;flex-wrap:wrap;gap:12px}.button.alt{background:white;color:var(--forest)}.button.alt:hover{background:#f2c15f;color:#40230e}.hero-shortcuts{display:flex;flex-wrap:wrap;gap:10px;margin-top:31px}.hero-shortcuts a{display:flex;align-items:center;gap:8px;padding:10px 13px;border:1px solid rgba(255,255,255,.38);border-radius:999px;background:rgba(255,255,255,.1);font-size:.83rem;font-weight:800;transition:.2s}.hero-shortcuts a span{color:#d8ef8d;font-size:.7rem}.hero-shortcuts a:hover{transform:translateY(-3px);background:rgba(255,255,255,.22)}.hero-note{margin-top:20px;font-size:.82rem;color:#e1eadf}@keyframes heroReveal{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}@keyframes brandGlow{0%,100%{transform:translateY(0);box-shadow:0 8px 18px rgba(23,77,45,.22)}50%{transform:translateY(-3px);box-shadow:0 14px 25px rgba(148,201,70,.34)}}
    .feature-row{position:relative;margin-top:-38px;z-index:2}.features{display:grid;grid-template-columns:repeat(3,1fr);background:white;border-radius:20px;box-shadow:var(--shadow);overflow:hidden}.feature{padding:22px 26px;border-right:1px solid #e5e7e1}.feature:last-child{border:0}.feature strong{display:block;font-family:Georgia,serif;font-size:1.15rem;color:var(--forest)}.feature span{font-size:.85rem;color:#657069}
    .intro{display:grid;grid-template-columns:.9fr 1.1fr;gap:64px;align-items:center}.photo-frame{position:relative}.photo-frame img{min-height:420px;object-fit:cover;border-radius:22px;box-shadow:var(--shadow)}.photo-tag{position:absolute;right:-22px;bottom:30px;background:var(--orange);color:white;padding:18px 20px;border-radius:14px;font-weight:800;box-shadow:var(--shadow)}.intro-copy p{color:#59635c;font-size:1.04rem}.amenities{display:flex;flex-wrap:wrap;gap:9px;margin-top:24px}.amenities span{border:1px solid #d1dccc;border-radius:999px;padding:7px 11px;color:var(--forest);font-weight:700;font-size:.83rem}
    .menu-section{background:var(--paper);border-block:1px solid #e6dcc6}.filters{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 28px}.filter{border:1px solid #bdcfbb;background:rgba(255,255,255,.46);padding:10px 16px;border-radius:999px;color:var(--forest);font:700 .85rem Arial;cursor:pointer;transition:transform .2s,background .2s,box-shadow .2s}.filter.active,.filter:hover{background:var(--forest);color:white;border-color:var(--forest);box-shadow:0 8px 18px rgba(23,77,45,.18);transform:translateY(-2px)}.menu-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.menu-grid.awaiting-selection .menu-card{display:none}.menu-choice{display:none;grid-column:1/-1;padding:54px 24px;text-align:center;border:1px solid #ccddb9;border-radius:22px;background:radial-gradient(circle at top,#f8ffe9,white 72%);box-shadow:0 18px 40px rgba(23,77,45,.08)}.menu-choice strong{display:block;color:var(--forest);font:700 clamp(1.55rem,3vw,2.25rem) Georgia,serif}.menu-choice span{display:block;margin:9px auto 0;color:#627064;max-width:460px}.menu-grid.awaiting-selection .menu-choice{display:block}.menu-card{background:#fffdf8;border-radius:18px;padding:21px 21px 14px;box-shadow:0 8px 24px rgba(23,77,45,.07);border:1px solid #e9e3d6;transition:transform .25s,box-shadow .25s}.menu-card:hover{transform:translateY(-5px);box-shadow:0 18px 34px rgba(23,77,45,.14)}.menu-card.featured{background:linear-gradient(145deg,#fffdf8 0%,#eef8df 100%);border:2px solid #a7cd74;box-shadow:0 14px 28px rgba(23,77,45,.12)}.menu-card.featured h3:before{content:'Morning special';display:block;margin-bottom:6px;color:var(--orange);font:800 .68rem Arial;letter-spacing:.11em;text-transform:uppercase}.menu-card h3{margin:0 0 13px;color:var(--forest);font:700 1.26rem Georgia,serif}.menu-card.hidden{display:none}.menu-card.visible{animation:menuRise .48s cubic-bezier(.22,1,.36,1) both}.menu-photo{height:148px;margin:-5px 0 15px;border-radius:12px;background-image:url('data:image/png;base64,');background-repeat:no-repeat;background-size:200% 200%;box-shadow:inset 0 0 0 1px rgba(255,255,255,.2);transition:transform .35s}.menu-card:hover .menu-photo{transform:scale(1.015)}.menu-photo.breakfast{background-position:left top}.menu-photo.biryani,.menu-photo.rice{background-position:right top}.menu-photo.starters,.menu-photo.curries,.menu-photo.noodles{background-position:left bottom}.menu-photo.tandoori,.menu-photo.breads{background-position:right bottom}.menu-photo.veg-biryani,.menu-photo.chicken-biryani,.menu-photo.mutton-biryani,.menu-photo.prawns-biryani,.menu-photo.fish-biryani{background-image:url('data:image/png;base64,');background-size:300% 200%}.menu-photo.veg-biryani{background-position:left top}.menu-photo.chicken-biryani{background-position:center top}.menu-photo.mutton-biryani{background-position:right top}.menu-photo.prawns-biryani{background-position:left bottom}.menu-photo.fish-biryani{background-position:center bottom}.menu-photo.veg-noodles,.menu-photo.egg-noodles,.menu-photo.chicken-noodles,.menu-photo.pulka-roti{background-image:url('data:image/png;base64,');background-size:200% 200%}.menu-photo.veg-noodles{background-position:left top}.menu-photo.egg-noodles{background-position:right top}.menu-photo.chicken-noodles{background-position:left bottom}.menu-photo.pulka-roti{background-position:right bottom}.item{display:grid;grid-template-columns:1fr auto;gap:10px;padding:8px 0;border-top:1px dotted #c7c5bd;font-size:.92rem}.item:first-of-type{border-top:0}.price{color:var(--orange);font-weight:800;white-space:nowrap}.menu-note{font-size:.8rem;color:#5e665f;margin:26px 0 0}@keyframes menuRise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}
    .gallery{max-width:940px;margin:auto}.gallery figure{margin:0;overflow:hidden;border-radius:24px;position:relative;background:var(--forest);box-shadow:var(--shadow)}.gallery img{height:min(62vw,560px);min-height:330px;object-fit:cover;transition:transform .35s}.gallery figure:hover img{transform:scale(1.025)}.gallery figcaption{position:absolute;inset:auto 0 0;padding:74px 28px 26px;color:#fff;background:linear-gradient(transparent,rgba(0,0,0,.8));font:700 1.12rem Georgia,serif}
    .catering{background:var(--forest);color:white}.catering-grid{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center}.catering .eyebrow{color:#d8ef8d}.catering h2{max-width:540px}.catering p{color:#e0eadc;max-width:560px}.occasions{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin:26px 0}.occasion{border:1px solid rgba(255,255,255,.24);border-radius:12px;padding:14px;background:rgba(255,255,255,.05);font-weight:700}.catering-image{border-radius:21px;overflow:hidden;box-shadow:0 18px 44px rgba(0,0,0,.32)}.catering-image img{min-height:330px;object-fit:cover}
    .biryani-controls{display:flex;flex-wrap:wrap;gap:9px;margin:-10px 0 26px;padding:15px;border-radius:15px;background:rgba(23,77,45,.08)}.biryani-controls[hidden]{display:none}.biryani-controls span{align-self:center;margin-right:4px;color:var(--forest);font-weight:800;font-size:.82rem}.biryani-filter{border:0;border-radius:999px;background:white;color:var(--forest);padding:8px 12px;font:700 .8rem Arial;cursor:pointer;transition:.2s}.biryani-filter.active,.biryani-filter:hover{background:var(--orange);color:white;transform:translateY(-1px)}
    .visit{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.visit-card{border-radius:20px;padding:32px;background:white;border:1px solid #e8e5dc}.visit-card.green{background:#dbeac8;border-color:#c9dfae}.visit-card h3{margin:0 0 10px;font:700 1.65rem Georgia,serif;color:var(--forest)}.visit-card p{margin:0 0 18px;color:#4f5d53}.contact-line{font-size:1.08rem;font-weight:800;color:var(--forest)}.reviews{background:#f4ead7}.review-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.review-card{padding:30px;border-radius:20px;background:white;box-shadow:0 10px 26px rgba(23,77,45,.08)}.review-stars{letter-spacing:.2em;color:#d78b18;font-size:1.25rem}.review-card h3{margin:11px 0 8px;color:var(--forest);font:700 1.45rem Georgia,serif}.review-card p{margin:0;color:#566258}.review-action{display:flex;align-items:center;justify-content:center;text-align:center;background:var(--forest);color:white}.review-action h3{color:white}.review-action p{color:#dcebd7}.review-action .button{background:#e9f4be;color:#174d2d;margin-top:20px}
    footer{background:#102d1c;color:#dfebdf;padding:34px 0 88px}.footer-row{display:flex;justify-content:space-between;align-items:end;gap:28px}.footer-right{text-align:right;color:#d8ef8d;font-size:.85rem}.copyright{display:block;margin-top:28px;padding-top:18px;border-top:1px solid rgba(255,255,255,.16);text-align:center;color:#c4d6c5;font-size:.82rem}.mobile-call{display:none}
    @media(max-width:800px){.links{display:none}.nav{min-height:76px}.brand-top .brand-mark{width:46px;height:46px;font-size:23px}.brand-title{font-size:1.08rem}.nav-call{font-size:.85rem;padding:10px 13px}.hero{min-height:610px}.hero-content{padding:68px 0}.features{grid-template-columns:1fr}.feature{border-right:0;border-bottom:1px solid #e5e7e1}.feature:last-child{border:0}.intro,.catering-grid,.visit{grid-template-columns:1fr;gap:30px}.review-grid{grid-template-columns:1fr}.photo-frame img{min-height:300px}.photo-tag{right:14px;bottom:14px}.menu-grid{grid-template-columns:1fr 1fr}.section{padding:64px 0}.section-head{display:block}.section-head p:last-child{margin-top:13px}.footer-row{display:block}.footer-right{text-align:left;margin-top:22px}.mobile-call{display:flex;position:fixed;right:16px;bottom:16px;z-index:11;width:56px;height:56px;padding:0;box-shadow:0 8px 25px rgba(15,60,30,.35);font-size:1.2rem}.mobile-call span{display:none}}
    @media(max-width:480px){.wrap{width:min(100% - 28px,1120px)}.menu-grid{grid-template-columns:1fr}.gallery img{height:330px}.hero h1{font-size:3.25rem}.hero-actions .button{width:100%}}

/* Anjana's Café original logo */
.brand-logo{
  width:64px;
  height:64px;
  object-fit:cover;
  object-position:center;
  border-radius:50%;
  flex:0 0 auto;
  box-shadow:0 8px 20px rgba(23,77,45,.20);
  border:2px solid rgba(255,255,255,.72);
}
.brand-logo-footer{width:46px;height:46px;box-shadow:none}
@media (max-width:700px){.brand-logo{width:50px;height:50px}.brand-logo-footer{width:40px;height:40px}}
